/* prog55_connected_components.c
 *
 * Re‑implementation of the original binary “prog55_connected_components”.
 *
 * The program expects an even number of command‑line arguments (after the
 * program name).  Each consecutive pair describes an undirected edge of a
 * graph whose vertices are numbered 0 … 7.  It builds the adjacency matrix,
 * validates the input, and then prints the connected components.
 *
 * Output format (exactly as the original binary):
 *
 *   <component‑index>: {v0,v1,…,vk}
 *
 * where the vertices of a component are listed in the order they are
 * discovered by a breadth‑first search (BFS) that scans neighbours in
 * increasing numeric order.  If the input is malformed the program prints
 *
 *   INVALID_INPUT
 *
 * followed by a newline (the behaviour of `puts`).
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8                     /* vertices are 0 … 7 */

int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------
     *  1.  Basic argument validation
     * -------------------------------------------------------------- */
    if ( (argc - 1) % 2 != 0 ) {          /* must be an even number of args */
        puts("INVALID_INPUT");
        return 0;
    }

    int adj[MAXV][MAXV] = {{0}};          /* adjacency matrix */
    int edge_cnt = (argc - 1) / 2;        /* number of edges */

    for (int i = 0; i < edge_cnt; ++i) {
        /*  The original binary reads the arguments in the order:
         *      argv[1 + 2*i] -> first vertex (u)
         *      argv[2 + 2*i] -> second vertex (v)
         *  and then stores adj[u][v] = adj[v][u] = 1.
         */
        int u = atoi(argv[1 + 2 * i]);   /* first vertex of the edge */
        int v = atoi(argv[2 + 2 * i]);   /* second vertex of the edge */

        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }

        adj[u][v] = 1;
        adj[v][u] = 1;
    }

    /* --------------------------------------------------------------
     *  2.  Bread‑first search to enumerate connected components
     * -------------------------------------------------------------- */
    int visited[MAXV] = {0};
    int queue[MAXV];
    int comp_index = 0;                  /* component number printed */

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;                    /* already part of a previous component */

        /* start a new component */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = 1;

        printf("%d:", comp_index);
        printf(" {");

        int first_vertex = 1;            /* controls commas between vertices */

        while (qhead < qtail) {
            int cur = queue[qhead++];
            if (!first_vertex)
                putchar(',');
            printf("%d", cur);
            first_vertex = 0;

            /* enqueue all not‑yet‑visited neighbours, scanning in order */
            for (int nb = 0; nb < MAXV; ++nb) {
                if (adj[cur][nb] && !visited[nb]) {
                    visited[nb] = 1;
                    queue[qtail++] = nb;
                }
            }
        }

        putchar('}');
        putchar('\n');
        ++comp_index;
    }

    return 0;
}
